// Instrument once, correctly; every service should have these four, defined the same way
var (
    httpRequestsTotal = promauto.NewCounterVec(prometheus.CounterOpts{
        Name: "http_requests_total",
        Help: "Total HTTP requests served.",
    }, []string{"service", "route", "method", "status"})       // low cardinality
    httpDuration = promauto.NewHistogramVec(prometheus.HistogramOpts{
        Name:    "http_request_duration_seconds",
        Help:    "HTTP request latency.",
        Buckets: []float64{0.005, 0.01, 0.025, 0.05, 0.1, 0.15, 0.2, 0.3, 0.5, 1, 2.5, 5, 10},
    }, []string{"service", "route", "method", "status"})
    inFlight = promauto.NewGauge(prometheus.GaugeOpts{
        Name: "http_requests_in_flight",
        Help: "Requests currently being served.",
    })
    buildInfo = promauto.NewGaugeVec(prometheus.GaugeOpts{
        Name: "build_info",
        Help: "Build metadata; value is always 1.",
    }, []string{"service", "git_sha", "version"})               // deploy markers
)

func Instrument(next http.Handler) http.Handler {
    return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
        inFlight.Inc()
        start := time.Now()
        rec := &statusRecorder{ResponseWriter: w, status: 200}
        route := routePattern(r)          // "/orders/{id}", NOT r.URL.Path

        // Sampling exemplars: attach a trace id to histogram observations
        var span trace.Span
        ctx := otel.GetTracerProvider().Tracer("http").Start(r.Context(), route)
        defer span.End()

        next.ServeHTTP(rec, r.WithContext(ctx))

        elapsed := time.Since(start).Seconds()
        labels := prometheus.Labels{
            "service": serviceName, "route": route,
            "method": r.Method, "status": strconv.Itoa(rec.status),
        }
        httpRequestsTotal.With(labels).Inc()
        httpDuration.With(labels).Observe(elapsed)
        inFlight.Dec()

        // Exemplar: link the slowest 1% of observations to their traces
        if elapsed > 0.5 {
            spanCtx := trace.SpanContextFromContext(r.Context())
            if spanCtx.IsValid() {
                prometheus.ExemplarObserver{Observer: httpDuration.With(labels)} // via client lib
            }
        }
    })
}
